import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-Jan-23 :: Ceph Tech Talk - Ceph for Storing MeerKAT Radio Telescope Data","description":"","frontmatter":{"title":"2020-Jan-23 :: Ceph Tech Talk - Ceph for Storing MeerKAT Radio Telescope Data","date":"2020-02-12T00:00:00.000Z","updated":"2020-02-12T00:00:00.000Z","tags":["[Ceph]","[MeerKAT]","[射电望远镜]","[数据存储]","[分布式存储系统]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-Jan-23_-_-_Ceph_Tech_Talk_-_Ceph_for_Storing_MeerKAT_Radio_Telescope_Data.md","filePath":"posts/2020/2020-Jan-23_-_-_Ceph_Tech_Talk_-_Ceph_for_Storing_MeerKAT_Radio_Telescope_Data.md","lastUpdated":1780459816000}'),i={name:"posts/2020/2020-Jan-23_-_-_Ceph_Tech_Talk_-_Ceph_for_Storing_MeerKAT_Radio_Telescope_Data.md"};function o(n,e,s,_,h,p){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>日期</strong>: 2020年1月</li><li><strong>主讲人</strong>: Thomas Bennett</li><li><strong>地点</strong>: 南非开普敦</li><li><strong>会议形式</strong>: 在线会议</li></ul><h4 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h4><p>Thomas Bennett在会议上分享了南非MeerKAT射电望远镜的数据存储解决方案，重点介绍了Ceph分布式存储系统的应用。他详细讨论了MeerKAT的科学应用、数据处理流程以及Ceph在其中的关键角色。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ol><li><p><strong>MeerKAT射电望远镜</strong>:</p><ul><li>MeerKAT是目前世界上最强大的射电望远镜。</li><li>位于南非卡鲁干旱地区，距离开普敦约90公里。</li><li>负责管理南非所有大型天文项目和设施。</li></ul></li><li><p><strong>Ceph存储系统</strong>:</p><ul><li>MeerKAT项目自2018年4月开始使用Ceph作为生产集群。</li><li>Ceph集群分为冷缓冲区和热缓冲区，热缓冲区主要使用SSD存储。</li><li>用户通过数据服务门户进行认证，并使用S3接口访问观测数据。</li></ul></li><li><p><strong>数据处理与科学发现</strong>:</p><ul><li>MeerKAT望远镜能够捕捉到高分辨率的射电图像，揭示了银河系中心黑洞等天体现象。</li><li>最近的一项研究发现了银河系中的新结构，这些发现已发表在《自然》杂志上。</li></ul></li><li><p><strong>Ceph集群配置与管理</strong>:</p><ul><li>目前运行的Ceph集群版本为Luminous，计划升级到Nautilus。</li><li>集群包括多个不同规模的集群，从几PB到几十PB不等。</li><li>使用Ansible进行部署，但正在考虑构建自己的部署方法。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>计划对Ceph集群进行升级，并测试EC池的使用。</li><li>考虑使用更高效的硬件配置，如增加处理器性能和使用更多的NVMe驱动器。</li><li>继续参与Ceph社区活动，包括组织meetups和参与Ceph会议。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成Ceph集群的升级和测试。</li><li>继续优化数据处理流程和存储管理。</li><li>加强与Ceph社区的交流和合作，推动技术进步和应用扩展。</li></ul><h4 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h4><ul><li><strong>主讲人</strong>: Thomas Bennett</li><li><strong>邮箱</strong>: <a href="mailto:tom@ska.ac.za" target="_blank" rel="noreferrer">tom@ska.ac.za</a></li><li><strong>网站</strong>: <a href="https://ska.ac.za" target="_blank" rel="noreferrer">https://ska.ac.za</a></li></ul><p>本次会议为与会者提供了关于MeerKAT射电望远镜及其数据存储解决方案的深入了解，特别是Ceph在大型科学项目中的应用和挑战。</p>',12)])])}const d=a(i,[["render",o]]);export{c as __pageData,d as default};
